D15 = add('D041-r016', 'unresolved_legal_evidence_D041_16', 'logic.coverage.all[1]', None, 'resolved', 'Even if your property is not covered under the Rent Stabilization Ordinance, you and your tenants have rights and responsibilities under the Just Cause Ordinance.', 'Coverage (LA + unit_subject_to_rso=false) spiegelt den Text exakt. Leaf streichen.')
D16 = add('D042-r002', 'unresolved_legal_evidence_D042_2', 'logic.coverage.all[1]', {'fact': 'rent_increase_notice_date', 'op': 'gte', 'value': '2026-02-02'}, 'resolved', 'Beginning February 2, 2026, a landlord can no longer include any additional percentage increase for utilities.', 'Wie D041-r002, belegt aus D042-Text; kanonischer Datumsfakt.')
D17 = add('D042-r003', 'unresolved_legal_evidence_D042_3', 'logic.coverage.all[1]', None, 'open', 'State law requires landlords to provide 30 days written advance notice of rent increases of less than 10%.', 'Offen: kleiner-als-10-Prozent-Schwelle hat keinen kanonischen Fakt (rent_increase_planned allein waere Unter-Spezifikation). Nichts erfunden.')
D18 = add('D042-r003', 'unresolved_legal_condition_state_notice_exemption', 'logic.exemptions', None, 'open', '', 'Offen: D042-Text enthaelt keine Ausnahme zur 30-Tage-Notice; Exemption-Leaf unbelegt, kein Ersatz.')
D19 = add('D043-r006', 'unresolved_legal_evidence_D043_6', 'logic.coverage.all[1]', None, 'resolved', 'A landlord may offset the accumulated rent against any relocation assistance, unless the relocation assistance is owed because a termination of tenancy is required by a governmental agency order to vacate or comply with an issued order for an unpermitted dwelling.', 'Coverage (LA + relocation_assistance_required) plus Exemptions (beide agency/order-Fakten) decken Text voll ab. Leaf streichen.')
D20 = add('D043-r014', 'unresolved_legal_evidence_D043_14', 'logic.coverage.all[1]', None, 'resolved', 'If the City of Los Angeles Planning Department has approved a tentative parcel or tract map for a condominium conversion, the tenant may elect to relocate without receiving a Notice to Terminate Tenancy from the landlord.', 'Coverage-Fakt tentative_parcel_map_approved_for_condo_conversion spiegelt den Text exakt. Leaf streichen.')
json.dump(rows, open('/tmp/gapfix_B.json', 'w'), indent=1, ensure_ascii=False)
res = sum(1 for r in rows if r['status'] == 'resolved')
opn = sum(1 for r in rows if r['status'] == 'open')
md = []
md.append('# Gap-Resolution Batch B (D040-D043, Los Angeles RSO/JCO)')
md.append('')
md.append('Ergebnis: %d resolved, %d offen (von %d Gap-Leaves). DB nicht geschrieben; Fundstellen nur vorgeschlagen.' % (res, opn, len(rows)))
md.append('')
md.append('Hinweis: resolved + replacement=null heisst redundanter Platzhalter -> Leaf ersatzlos streichen und all-Kette kollabieren. Zitate <=300 Zeichen,Whitespace normalisiert.')
md.append('')
for r in rows:
    md.append('## ' + r['team_rule_id'] + ' / ' + r['gap_fact'])
    md.append('')
    md.append('Pfad: ' + r['path'] + ' | Status: ' + r['status'])
    md.append('')
    md.append('Entscheidung: ' + r['rationale'])
    md.append('')
    md.append('Ersatz: ' + (json.dumps(r['replacement']) if r['replacement'] else 'null (streichen bzw. offen)'))
    md.append('')
    md.append('Beleg: ' + ('> ' + r['evidence_quote'] if r['evidence_quote'] else '> (kein Beleg im Korpus)'))
    md.append('')
open('reports/gap_resolution_B.md', 'w').write(chr(10).join(md))
print('WROTE rows=%d resolved=%d open=%d' % (len(rows), res, opn))
